import{_ as o,o as s,c as n,ah as a}from"./chunks/framework.D1ler-R1.js";const i="/projects/SpiderPi_Pro/en/latest/assets/image2.cMMNUvrM.png",r="/projects/SpiderPi_Pro/en/latest/assets/image4.Bsq_fcTQ.png",l="/projects/SpiderPi_Pro/en/latest/assets/image1.DQhPvFfW.png",e="/projects/SpiderPi_Pro/en/latest/assets/image4.DhgX0N_I.png",d="/projects/SpiderPi_Pro/en/latest/assets/image5.COm58bsh.png",c="/projects/SpiderPi_Pro/en/latest/assets/image8.B9QP2hyF.png",v=JSON.parse('{"title":"8. Group Control Course","description":"","frontmatter":{},"headers":[],"relativePath":"docs/12_mass_control.md","filePath":"docs/12_mass_control.md"}'),h={name:"docs/12_mass_control.md"};function p(g,t,u,m,b,y){return s(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="_8-group-control-course" tabindex="-1">8. Group Control Course <a class="header-anchor" href="#_8-group-control-course" aria-label="Permalink to &quot;8. Group Control Course&quot;">​</a></h1><h2 id="_8-1-handle-control" tabindex="-1">8.1 Handle Control <a class="header-anchor" href="#_8-1-handle-control" aria-label="Permalink to &quot;8.1 Handle Control&quot;">​</a></h2><h3 id="_8-1-1-getting-ready" tabindex="-1">8.1.1 Getting ready <a class="header-anchor" href="#_8-1-1-getting-ready" aria-label="Permalink to &quot;8.1.1 Getting ready&quot;">​</a></h3><p>Step 1: insert the handle receiver into any USB interface on Raspberry Pi expansion board.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Note: please insert the handle receiver before the device boots up.</p></div><p>Step 2: please bring your own two triple A dry batteries.</p><img loading="lazy" height="482" width="1288" src="'+i+'" alt="loading"><h3 id="_8-1-2-device-connection" tabindex="-1">8.1.2 Device connection <a class="header-anchor" href="#_8-1-2-device-connection" aria-label="Permalink to &quot;8.1.2 Device connection&quot;">​</a></h3><p>Step 1: turn on the switch of SpiderPi Pro.</p><p>Step 2: turn on the switch on the handle. At this time, two LED lights will flash simultaneously.</p><p>Step 3: please wait for a while. Then the robot will pair with the handle automatically. After successful pairing, the green light will keep lighting up.</p><p>If the handle doesn&#39;t connect to the robot within 30s or there is no operation on the handle within 5 minutes after turning on, it will enter sleep mode. And you can press &quot;<strong>START</strong>&quot; to activate the handle.</p><h3 id="_8-1-3-mode-introduction" tabindex="-1">8.1.3 Mode introduction <a class="header-anchor" href="#_8-1-3-mode-introduction" aria-label="Permalink to &quot;8.1.3 Mode introduction&quot;">​</a></h3><p>There are two modes, including <strong>body control mode</strong> and <strong>robotic arm control mode</strong>.</p><p>Way to switch the mode: press &quot;<strong>START</strong>&quot; and &quot;<strong>SELECT</strong>&quot; key at the same time. When the handle &quot;<strong>beeps</strong>&quot; once, the mode is switched to body control mode. If the handle &quot;<strong>beeps</strong>&quot; twice, the mode is switched to robotic arm control mode</p><h3 id="_8-1-4-key-function" tabindex="-1">8.1.4 Key function <a class="header-anchor" href="#_8-1-4-key-function" aria-label="Permalink to &quot;8.1.4 Key function&quot;">​</a></h3><p>The function of each key under body control mode is listed below.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Key</th><th style="text-align:center;">Function</th></tr></thead><tbody><tr><td style="text-align:center;">START</td><td style="text-align:center;">the body will return to the initial posture</td></tr><tr><td style="text-align:center;">L2</td><td style="text-align:center;">turn left 30 degree</td></tr><tr><td style="text-align:center;">R2</td><td style="text-align:center;">turn right 30 degree</td></tr><tr><td style="text-align:center;">↑ /move up left slider</td><td style="text-align:center;">go straight forward 50mm</td></tr><tr><td style="text-align:center;">↓/move down left slider</td><td style="text-align:center;">go straight backward 50mm</td></tr><tr><td style="text-align:center;">← /move left left slider</td><td style="text-align:center;">move left 50mm</td></tr><tr><td style="text-align:center;">→ /move right left slider</td><td style="text-align:center;">move backward 50mm</td></tr><tr><td style="text-align:center;"><strong>△</strong></td><td style="text-align:center;">attack</td></tr><tr><td style="text-align:center;"><strong>×</strong></td><td style="text-align:center;">twist</td></tr><tr><td style="text-align:center;"><strong>◻</strong></td><td style="text-align:center;">wave</td></tr><tr><td style="text-align:center;">〇</td><td style="text-align:center;">kick</td></tr><tr><td style="text-align:center;"><strong>R1</strong></td><td style="text-align:center;">dance</td></tr></tbody></table><p>The function of each key under robotic arm control mode is listed below.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Key</th><th style="text-align:center;">Function</th></tr></thead><tbody><tr><td style="text-align:center;">START</td><td style="text-align:center;">robotic arm returns to initial posture</td></tr><tr><td style="text-align:center;">L2</td><td style="text-align:center;">No.25 servo opens</td></tr><tr><td style="text-align:center;">R2</td><td style="text-align:center;">No.25 servo close</td></tr><tr><td style="text-align:center;">move up left slider</td><td style="text-align:center;">No.21 servo moves forward</td></tr><tr><td style="text-align:center;">move down left slider</td><td style="text-align:center;">No.21 servo moves backward</td></tr><tr><td style="text-align:center;">move left left slider</td><td style="text-align:center;">No.22 servo moves forward</td></tr><tr><td style="text-align:center;">move right left slider</td><td style="text-align:center;">No.22 servo moves backward</td></tr><tr><td style="text-align:center;"><strong>◻</strong></td><td style="text-align:center;">No.23 servo moves backward</td></tr><tr><td style="text-align:center;"><strong>△</strong></td><td style="text-align:center;">No.23 servo moves forward</td></tr><tr><td style="text-align:center;"><strong>×</strong></td><td style="text-align:center;">No.24 servo moves backward</td></tr><tr><td style="text-align:center;">〇</td><td style="text-align:center;">No.24 servo moves forward</td></tr></tbody></table><p>The ID of servos on the robot arm is as below:</p><img loading="lazy" height="821" width="768" class="common_img" src="'+r+'"><h2 id="_8-2-group-control" tabindex="-1">8.2 Group Control <a class="header-anchor" href="#_8-2-group-control" aria-label="Permalink to &quot;8.2 Group Control&quot;">​</a></h2><h3 id="_8-2-1-getting-ready" tabindex="-1">8.2.1 Getting ready <a class="header-anchor" href="#_8-2-1-getting-ready" aria-label="Permalink to &quot;8.2.1 Getting ready&quot;">​</a></h3><p>(1) 2 or above SpiderPi Pros are needed in group control.</p><p>(2) Set up development environment. Please refer to the tutorial in &quot;<a href="https://docs.hiwonder.com/projects/SpiderPi_Pro/en/latest/docs/6_remote_tool.html#vnc-installation-and-connection" target="_blank" rel="noreferrer">Remote Desktop Installation and Connection-&gt;3.1VNC Installation and Connection</a>&quot; to download and install VNC.</p><h3 id="_8-2-2-program-logic" tabindex="-1">8.2.2 Program logic <a class="header-anchor" href="#_8-2-2-program-logic" aria-label="Permalink to &quot;8.2.2 Program logic&quot;">​</a></h3><p>First, configure the master and the salve to one network. Then the master sends the action command to the slave through group sending program so as to achieve group controlling.</p><h3 id="_8-2-3-operation-steps" tabindex="-1">8.2.3 Operation steps <a class="header-anchor" href="#_8-2-3-operation-steps" aria-label="Permalink to &quot;8.2.3 Operation steps&quot;">​</a></h3><ul><li><strong>configure the master</strong></li></ul><p>(1) Firstly, pick one robot as the master. After turning on the master robot, remotely connect to the desktop. Take <strong>&quot;HW-DDD123FE&quot;</strong> robot for example.</p><img loading="lazy" height="140" width="360" class="common_img" src="'+l+'"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>please take down the hotspot name which will be used in the later step.</p></div><p>(2) Open command line terminal. Then enter the command <code>cd hiwonder-toolbox/</code> and press <code>Enter</code> to enter the catalog of WiFi configuration file.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hiwonder-toolbox/</span></span></code></pre></div><p>(3) Enter <code>vim wifi_conf.py</code> command and press <code>Enter</code> to open Wi-Fi configuration file with vi editor.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wifi_conf.py</span></span></code></pre></div><p>(4) Press <code>i</code> key to enter the editing mode.</p><img loading="lazy" height="170" width="583" class="common_img" src="'+e+'"><p>(5) Modify the WiFi password of the master as &quot;<strong>hiwonder</strong>&quot; and then uncomment this code shown in the below figure：</p><img loading="lazy" height="23" width="395" class="common_img" src="'+d+'"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>the password should be 8 digits or above.</p></div><p>(6) After modification, press <code>Esc</code> key to exit the editing mode. And input <code>:wq</code> to save and exit.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:wq</span></span></code></pre></div><p>(7) Input command <code>sudo reboot</code> to reboot the device. Please do not skip this step.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reboot</span></span></code></pre></div><ul><li><strong>Configure the slave</strong></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>we use a single slave to demonstrate. If you need to configure multiple slaves, you can also follow the below steps to operate.</p></div><p>(1) Open command line terminal. Then enter command and press <code>Enter</code> to enter the catalog of WiFi configuration file.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hiwonder-toolbox/</span></span></code></pre></div><p>(2) Open the WiFi configuration file with vi editor. Enter command and press <code>Enter</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wifi_conf.py</span></span></code></pre></div><p>(3) Press <code>i</code> key to enter editing mode.</p><img loading="lazy" height="170" width="583" class="common_img" src="'+e+'"><p>(4) Modify the WiFi password of the slave as &quot;<strong>hiwonder</strong>&quot; same as the master,and the ID as HW-DDD123FE. And then uncomment this code shown in the below figure:</p><img loading="lazy" height="252" width="749" class="common_img" src="'+c+'"><p>(5) After modification, press &quot;<strong>Esc</strong>&quot; key to exit the editing mode. And input &quot;<strong>:wq</strong>&quot; to save and exit.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:wq</span></span></code></pre></div><p>(6) Enter command to reboot the device. Please do not skip this step.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reboot</span></span></code></pre></div><ul><li><strong>group control</strong></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>During group control, please turn on the master first, then the slave.</p></div><p>(1) Place the master and slave robot on the open ground. And ensure there is certain interval between each robot. Insert the PS2 handle receiver into the USB interface on the master.</p><p>(2) Connect to the master, open the command line terminal, enter the command , and press <code>Enter</code> to navigate to the directory where the group control file is located.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spiderpi/functions/</span></span></code></pre></div><p>(3) Enter the command and press <code>Enter</code> to start the group control server.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> multi_control_server.py</span></span></code></pre></div><p>(4) Refer to the instruction of LAN mode connection in &quot;<a href="https://docs.hiwonder.com/projects/SpiderPi_Pro/en/latest/docs/2_Getting%20Ready.html#app-installation-and-connection" target="_blank" rel="noreferrer"><strong>Quick User Experience\\2.1 APP Installation and Connection</strong></a>&quot; to obtain the IP address of the slave for connection.</p><p>(5) After the slave is connected, open the command line terminal, enter the command <code>cd spiderpi/functions/</code>, and press <code>Enter</code> to access the directory where the group control file is located.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spiderpi/functions/</span></span></code></pre></div><p>(6) Enter the command and press <code>Enter</code> to start the group control client.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> multi_control_client.py</span></span></code></pre></div><p>(7) Open the handle for connection, then you can control SpiderPi Pro with it.</p><h3 id="_8-2-4-project-outcome" tabindex="-1">8.2.4 Project Outcome <a class="header-anchor" href="#_8-2-4-project-outcome" aria-label="Permalink to &quot;8.2.4 Project Outcome&quot;">​</a></h3><p>After the program runs, the mater and slave robots will execute the same action group.</p>',75)])])}const f=o(h,[["render",p]]);export{v as __pageData,f as default};
